  render(){const query=this.filter.value.toLocaleLowerCase(),values=this.records.filter(record=>!query||Object.values(record).some(value=>String(value).toLocaleLowerCase().includes(query)));this.body.replaceChildren(...values.map(record=>{const row=document.createElement('tr');row.record=record;for(const column of this.columns){const cell=row.insertCell();cell.textContent=text(column.value(record));cell.title=cell.textContent}return row}));this.empty.hidden=values.length!==0;if(this.connected&&this.loaded&&values.length===0)this.empty.textContent='没有项目'}
  openMenu(event,record){this.menu.replaceChildren(...this.actions.filter(action=>!action.visible||action.visible(record)).map(action=>{const button=document.createElement('button');button.textContent=action.title;button.classList.toggle('danger',action.danger===true);button.onclick=()=>{this.menu.hidden=true;this.execute(action,record)};return button}));if(this.menu.children.length)placeMenu(this.menu,event)}
